#!/usr/bin/env python3
"""
Web: bank-transfer receipts switch to "Successful Transaction" once the bank confirms.

The receipt checks every few seconds (for about a minute) and updates itself; if the
transfer fails instead, it says so and the money is back in the wallet.
Needs the backend update oam-withdrawal-receipt-status-backend.

Unzip in the web project root (with package.json), then:
    python3 apply_withdrawal_receipt_status_web.py
    npm run build
"""
import json, shutil, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
DATA = json.loads('{"edits": {"src/services/payouts.ts": [["    return data;\\n  },\\n\\n  /** Cancel a queued withdrawal — the money goes back to the wallet. */\\n  async cancel(id: string): Promise<Withdrawal> {\\n    const { data } = await api.post<Withdrawal>(`/payouts/withdrawals/${id}/cancel/`, {});\\n", "    return data;\\n  },\\n\\n  /** One withdrawal, re-checked with the bank provider while it\'s processing. */\\n  async get(id: string): Promise<Withdrawal> {\\n    const { data } = await api.get<Withdrawal>(`/payouts/withdrawals/${id}/`);\\n    return data;\\n  },\\n\\n  /** Cancel a queued withdrawal — the money goes back to the wallet. */\\n  async cancel(id: string): Promise<Withdrawal> {\\n    const { data } = await api.post<Withdrawal>(`/payouts/withdrawals/${id}/cancel/`, {});\\n"]], "src/pages/services/Transfer.tsx": [["import { apiErrorMessage } from \\"../../lib/api\\";\\nimport { VerifyGate } from \\"./BuyData\\";\\nimport { useDebounced } from \\"../../hooks/useDebounced\\";\\nimport { useTranslation } from \\"react-i18next\\";\\n\\n/** Withdraw wallet funds to a Nigerian bank account. */\\n", "import { apiErrorMessage } from \\"../../lib/api\\";\\nimport { VerifyGate } from \\"./BuyData\\";\\nimport { useDebounced } from \\"../../hooks/useDebounced\\";\\nimport { useWithdrawalPoll } from \\"../../hooks/useWithdrawalPoll\\";\\nimport { useTranslation } from \\"react-i18next\\";\\n\\n/** Withdraw wallet funds to a Nigerian bank account. */\\n"], ["    onSettled: () => pinStatus.refetch(),\\n  });\\n\\n  const withdraw = useMutation({\\n    mutationFn: () => payoutsApi.withdraw({ bank_account_id: accountId, amount: Number(amount), pin }),\\n    onSuccess: (w) => {\\n", "    onSettled: () => pinStatus.refetch(),\\n  });\\n\\n  // While the bank confirms, keep checking and update the receipt when it settles.\\n  const [pollId, setPollId] = useState<string | null>(null);\\n  useWithdrawalPoll(pollId, (w) => {\\n    setPollId(null);\\n    queryClient.invalidateQueries({ queryKey: [\\"wallet\\"] });\\n    queryClient.invalidateQueries({ queryKey: [\\"payouts\\"] });\\n    if (w.status === \\"success\\") {\\n      setReceipt((r) => (r ? { ...r, statusLabel: \\"Successful Transaction\\" } : r));\\n      setDone(t(\\"xferbank.completed\\", \\"₦{{amount}} sent successfully.\\", { amount: Number(w.amount).toLocaleString() }));\\n    } else {\\n      setReceipt(null);\\n      setDone(undefined);\\n      const reason = (w.failure_reason as string) || \\"\\";\\n      setError(reason ? t(\\"withdraw.errFailedReason\\", { reason }) : t(\\"withdraw.errFailed\\"));\\n    }\\n  });\\n\\n  const withdraw = useMutation({\\n    mutationFn: () => payoutsApi.withdraw({ bank_account_id: accountId, amount: Number(amount), pin }),\\n    onSuccess: (w) => {\\n"], ["      setPin(\\"\\");\\n      if (w.status === \\"queued\\") { setQueued(w); return; }   // waiting for OAM\'s balance\\n      const pending = w.status === \\"pending\\" || w.status === \\"processing\\";\\n      setReceipt({\\n        amount: Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2 }),\\n        date: formatReceiptDate(new Date()),\\n", "      setPin(\\"\\");\\n      if (w.status === \\"queued\\") { setQueued(w); return; }   // waiting for OAM\'s balance\\n      const pending = w.status === \\"pending\\" || w.status === \\"processing\\";\\n      if (pending) setPollId(String(w.id));\\n      setReceipt({\\n        amount: Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2 }),\\n        date: formatReceiptDate(new Date()),\\n"]], "src/pages/services/Withdraw.tsx": [["import { apiErrorMessage } from \\"../../lib/api\\";\\nimport { VerifyGate } from \\"./BuyData\\";\\nimport { useDebounced } from \\"../../hooks/useDebounced\\";\\nimport { useTranslation } from \\"react-i18next\\";\\n\\n/** Withdraw wallet funds to a Nigerian bank account. */\\n", "import { apiErrorMessage } from \\"../../lib/api\\";\\nimport { VerifyGate } from \\"./BuyData\\";\\nimport { useDebounced } from \\"../../hooks/useDebounced\\";\\nimport { useWithdrawalPoll } from \\"../../hooks/useWithdrawalPoll\\";\\nimport { useTranslation } from \\"react-i18next\\";\\n\\n/** Withdraw wallet funds to a Nigerian bank account. */\\n"], ["  });\\n  const hasPin = pinStatus.data?.has_pin;\\n\\n  const withdraw = useMutation({\\n    mutationFn: () => payoutsApi.withdraw({ bank_account_id: accountId, amount: Number(amount), pin }),\\n    onSuccess: (w) => {\\n", "  });\\n  const hasPin = pinStatus.data?.has_pin;\\n\\n  // While the bank confirms, keep checking and update the receipt when it settles.\\n  const [pollId, setPollId] = useState<string | null>(null);\\n  useWithdrawalPoll(pollId, (w) => {\\n    setPollId(null);\\n    queryClient.invalidateQueries({ queryKey: [\\"wallet\\"] });\\n    queryClient.invalidateQueries({ queryKey: [\\"payouts\\"] });\\n    if (w.status === \\"success\\") {\\n      setReceipt((r) => (r ? { ...r, statusLabel: \\"Successful Transaction\\" } : r));\\n      setDone(t(\\"xferbank.completed\\", \\"₦{{amount}} sent successfully.\\", { amount: Number(w.amount).toLocaleString() }));\\n    } else {\\n      setReceipt(null);\\n      setDone(undefined);\\n      const reason = (w.failure_reason as string) || \\"\\";\\n      setError(reason ? t(\\"withdraw.errFailedReason\\", { reason }) : t(\\"withdraw.errFailed\\"));\\n    }\\n  });\\n\\n  const withdraw = useMutation({\\n    mutationFn: () => payoutsApi.withdraw({ bank_account_id: accountId, amount: Number(amount), pin }),\\n    onSuccess: (w) => {\\n"], ["      setAmount(\\"\\");\\n      setPin(\\"\\");\\n      if (w.status === \\"queued\\") { setQueued(w); return; }   // waiting for OAM\'s balance\\n      setReceipt({\\n        amount: Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2 }),\\n        date: new Date().toISOString(),\\n        recipientName: w.account_name || t(\\"withdraw.yourBank\\"),\\n        recipientSub: `${w.bank_name ?? \\"Bank\\"} · ${w.account_number ?? \\"\\"}`,\\n        senderName: `${user?.first_name ?? \\"\\"} ${user?.last_name ?? \\"\\"}`.trim() || \\"You\\",\\n", "      setAmount(\\"\\");\\n      setPin(\\"\\");\\n      if (w.status === \\"queued\\") { setQueued(w); return; }   // waiting for OAM\'s balance\\n      const pending = w.status === \\"pending\\" || w.status === \\"processing\\";\\n      if (pending) setPollId(String(w.id));\\n      setReceipt({\\n        amount: Number(amount).toLocaleString(undefined, { minimumFractionDigits: 2 }),\\n        date: new Date().toISOString(),\\n        statusLabel: pending ? \\"Transfer Processing\\" : \\"Successful Transaction\\",\\n        recipientName: w.account_name || t(\\"withdraw.yourBank\\"),\\n        recipientSub: `${w.bank_name ?? \\"Bank\\"} · ${w.account_number ?? \\"\\"}`,\\n        senderName: `${user?.first_name ?? \\"\\"} ${user?.last_name ?? \\"\\"}`.trim() || \\"You\\",\\n"], ["        type: \\"Withdrawal\\",\\n        reference: w.reference ?? \\"\\",\\n      });\\n      const pending = w.status === \\"pending\\" || w.status === \\"processing\\";\\n      setDone(\\n        pending\\n          ? t(\\"withdraw.onWay\\", { amount: Number(amount).toLocaleString(), name: w.account_name || t(\\"withdraw.yourBank\\") })\\n", "        type: \\"Withdrawal\\",\\n        reference: w.reference ?? \\"\\",\\n      });\\n      setDone(\\n        pending\\n          ? t(\\"withdraw.onWay\\", { amount: Number(amount).toLocaleString(), name: w.account_name || t(\\"withdraw.yourBank\\") })\\n"]]}, "files": {"src/hooks/useWithdrawalPoll.ts": "import { useEffect, useRef } from \\"react\\";\\nimport { payoutsApi, type Withdrawal } from \\"../services/payouts\\";\\n\\nconst FINAL = [\\"success\\", \\"failed\\", \\"reversed\\", \\"cancelled\\"];\\n\\n/**\\n * After a bank transfer comes back \\"processing\\", check it every few seconds\\n * (the backend re-asks the payout provider) and report once it settles, so the\\n * receipt can flip from \\"Transfer Processing\\" to \\"Successful Transaction\\".\\n * Stops after ~1 minute; the wallet history catches up later either way.\\n */\\nexport function useWithdrawalPoll(id: string | null, onFinal: (w: Withdrawal) => void, everyMs = 3000, tries = 20) {\\n  const cb = useRef(onFinal);\\n  cb.current = onFinal;\\n\\n  useEffect(() => {\\n    if (!id) return;\\n    let n = 0;\\n    let stopped = false;\\n    const timer = setInterval(async () => {\\n      n += 1;\\n      try {\\n        const w = await payoutsApi.get(id);\\n        if (!stopped && FINAL.includes(String(w.status))) {\\n          stopped = true;\\n          clearInterval(timer);\\n          cb.current(w);\\n          return;\\n        }\\n      } catch {\\n        /* keep trying */\\n      }\\n      if (n >= tries) clearInterval(timer);\\n    }, everyMs);\\n    return () => { stopped = true; clearInterval(timer); };\\n  }, [id, everyMs, tries]);\\n}\\n"}, "locales": {}}')
TAG = 'wdstatus'
if not (ROOT / 'package.json').exists():
    print("Run this from the web project root (the folder with package.json)."); sys.exit(1)

plan, skipped = {}, []
for rel, pairs in DATA["edits"].items():
    p = ROOT / rel
    if not p.exists():
        print("Missing:", rel, "- nothing changed."); sys.exit(1)
    s = p.read_text(encoding="utf-8")
    if all(new in s for _, new in pairs):
        skipped.append(rel); continue
    for old, new in pairs:
        if s.count(old) != 1:
            print(rel, "doesn't look as expected - nothing changed. Send me that file and I'll adapt the update."); sys.exit(1)
        s = s.replace(old, new)
    plan[p] = s
for p, s in plan.items():
    shutil.copy2(p, p.with_name(p.name + ".bak-" + TAG))
    p.write_text(s, encoding="utf-8"); print("patched:", p.relative_to(ROOT))
for rel in skipped: print("already up to date:", rel)
for rel, text in DATA.get("files", {}).items():
    p = ROOT / rel; p.parent.mkdir(parents=True, exist_ok=True)
    if p.exists() and p.read_text(encoding="utf-8") == text:
        print("up to date:", rel); continue
    p.write_text(text, encoding="utf-8"); print("wrote:", rel)
for base, (dirrel, langs) in DATA.get("locales", {}).items():
    d = ROOT / dirrel; n = 0
    for lang, kv in langs.items():
        p = d / (lang + ".json")
        if not p.exists(): continue
        raw = p.read_text(encoding="utf-8"); obj = json.loads(raw); node = obj
        for part in base.split("."): node = node.setdefault(part, {})
        node.update(kv)
        p.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + ("\n" if raw.endswith("\n") else ""), encoding="utf-8"); n += 1
    print("translations:", base, "in", n, "languages")
print("Done.")
